-- 10 · Replace the activity bank with the curated 84-activity list (Google Sheet,
--       loaded 2026-08-05). The previous 33 seeded items are deleted outright — the
--       user confirmed they are obsolete. Nothing references activity_bank_items:
--       adding an activity to a plan COPIES its values into plan_activities, so
--       schools' existing plans are unaffected.
--
--       Schema changes this needs:
--         + metrics  — the sheet's "מדדי הצלחה ויעדים"; prefills the activity's
--                      metrics field when a principal adds it to the plan.
--         + position — the sheet's row order is meaningful; preserve it.
--         - goal     — dropped: the sheet has one purpose field ("מטרת העל"), which
--                      maps to `short`. A second near-identical column would drift.

alter table public.activity_bank_items add column if not exists metrics  text not null default '';
alter table public.activity_bank_items add column if not exists position int  not null default 0;
alter table public.activity_bank_items drop column if exists goal;

delete from public.activity_bank_items;


-- עיקרון 3 · הטמעת AI כתשתית (12 פעילויות)
insert into public.activity_bank_items (
  scope, municipality_id, principle_id, slug, title, category, source,
  short, description, metrics, audience, contact, position, is_active
)
select 'municipal',
       (select id from public.municipalities where slug = 'holon'),
       (select id from public.principles
         where scope = 'municipal' and title = 'הטמעת AI כתשתית'),
       x.slug, x.title, '', 'עירוני'::public.task_source,
       x.short, x.description, x.metrics, x.audience, x.contact, x.position, true
from (values
    ('p3-01', 'מינוי מוביל בינה מלאכותית בית-ספרי', 'ביסוס מנהיגות מקצועית להטמעת AI', 'הגדרת תפקיד רשמי לאיש צוות שיוביל את ההטמעה, יחנוך מורים, וינהל את מאגר הידע הבית-ספרי בתחום.', 'כתיבת הגדרת תפקיד מפורטת עד ה-1.9; שריון שעת חלון שבועית במערכת לטובת חניכת עמיתים; פגישת סטטוס חודשית.', 'צוות הוראה והנהלה', 'אגף חדשנות', 1),
    ('p3-02', 'סדנת חשיפה "קו-פיילוט לכל מורה"', 'חשיפה והפגת חששות משימוש ב-AI', 'סדנת בזק חווייתית בישיבת המורים הראשונה של השנה, שנועדה להפיג חרדות ולייצר מוטיבציה לשימוש בכלי AI.', 'נוכחות של 100% מצוות ההוראה; 70% מהמורים מדווחים על ביטחון בסיסי ורצון להתנסות בכלי אחד לפחות.', 'כלל צוות ההוראה', 'פסג״ה חולון', 2),
    ('p3-03', 'שילוב "עוגן AI" קבוע בישיבות המליאה', 'הטמעת שגרת למידה ושיתוף ב-AI', 'הקצאת 20 דקות קבועות בכל ישיבת מליאה או קל"מ לחשיפה, התנסות מעשית ושיתוף הצלחות.', 'קיום 8 סשנים לפחות במהלך השנה; מינימום 5 מורים שונים יציגו כלי או מערך שיעור מבוסס AI שיצרו.', 'צוות הוראה', 'אגף חדשנות', 3),
    ('p3-04', 'ניתוח נתונים וניסוח איגרת פתיחת שנה ב-AI', 'ייעול עבודת ההנהלה ושיפור התקשורת', 'שימוש בבינה מלאכותית על ידי צוות ההנהלה לניתוח נתוני משוב וניסוח איגרת ממוקדת להורים.', 'שליחת האיגרת להורים בשבוע הראשון של ספטמבר; קיצור זמן העבודה הניהולי על המסמך ב-50% לפחות.', 'צוות הנהלה והורים', 'אגף חדשנות', 4),
    ('p3-05', 'פיתוח מאגר יחידות לימוד מבודלות מבוססות AI', 'קידום למידה מותאמת אישית בעזרת AI', 'שימוש ב-AI כ"עוזר הוראה" ליצירת מערכי שיעור ומשימות הערכה ברמות קושי שונות המותאמים לשונות בכיתה.', 'הקמת תיקיית ענן מוסדית; כל מורה מעלה למאגר לפחות 3 יחידות לימוד מבודלות שבוקרו על ידו.', 'צוות הוראה ותלמידים', 'פסג״ה חולון', 5),
    ('p3-06', 'גיבוש "אמנת AI" מוסדית מול מחלקת התקשוב', 'הסדרת השימוש ב-AI ויצירת מוגנות', 'עבודה משותפת עם האקו-סיסטם העירוני והנהגת ההורים ליצירת הנחיות והרשאות בטוחות לשימוש ב-AI.', 'אישור ופרסום מסמך מדיניות עד סוף מחצית א''; קיום מפגש יידוע להורים בנושא מוגנות דיגיטלית.', 'תלמידים, הורים וצוות', 'אגף חדשנות', 6),
    ('p3-07', 'אוטומציה של שגרות מנהלה ומזכירות', 'ייעול תהליכי מנהלה והפחתת עומס', 'הדרכת צוות המזכירות והמנהלה בשימוש ב-AI לסיכום ישיבות פדגוגיות וייעול עבודת הבק-אופיס.', 'סיכום 100% מישיבות ההנהלה באמצעות בינה מלאכותית; הפחתת עומס של לפחות 3 שעות עבודה שבועיות לצוות המנהלה.', 'צוות מנהלה ומזכירות', 'אגף חדשנות', 7),
    ('p3-08', 'המרת "זמן רובוטי" לזמן אנושי – ויתור ארגוני', 'פינוי זמן פדגוגי לטובת קשר אישי', 'צמצום מטלות מנהלה למורים לטובת אוטומציה, ושריון הזמן שנחסך לטובת מנטורינג ושיחות אישיות.', 'עלייה מדידה של לפחות 15% במספר השעות האפקטיביות המוקדשות לשיח רגשי וליווי פרטני.', 'צוות הוראה ותלמידים', 'אגף חדשנות', 8),
    ('p3-09', 'הטמעת סביבת חקר ולמידה לתלמידים מבוססת AI', 'פיתוח חשיבה ביקורתית ואוריינות AI', 'הכנסת בוט פנימי או כלי מבוקר כסביבת עבודה לחקר מודרך ולפיתוח חשיבה ביקורתית אצל התלמידים.', 'הטמעת הכלי בלפחות 2 שכבות גיל בוגרות; ביצוע פרויקט חקר אחד במחצית שבו התלמידים מבקרים תוצרי AI.', 'תלמידים', 'אגף חדשנות', 9),
    ('p3-10', 'יצירת שותפויות ללמידת עמיתים עירונית', 'הרחבת רשת הקשרים ולמידת עמיתים', 'חיבור בית הספר למוסד חינוכי נוסף בעיר שכבר החל בהטמעה או לחברת טכנולוגיה קהילתית.', 'קיום לפחות 2 מפגשי למידה (פיזיים/מקוונים) בשנה; אימוץ פרקטיקת ניהול/הוראה אחת מהשותף העירוני.', 'צוות הנהלה והוראה', 'אגף חדשנות', 10),
    ('p3-11', 'שילוב פרויקט AI לשכבת ח'' (עם "בית רותר")', 'חשיפה מעשית לטכנולוגיות מתקדמות', 'העתקת חלק משעות הלימוד של שכבת ח'' למרכז "בית רותר" לפרויקט AI מעשי מחוץ לבית הספר.', '100% מתלמידי שכבת ח'' משתתפים; הצגת לפחות 5 תוצרי AI מתקדמים בתערוכת סוף שנה.', 'תלמידי שכבת ח''', 'אגף חדשנות', 11),
    ('p3-12', 'סדנת צוות בנושא בינה מלאכותית (עם "בית רותר")', 'פיתוח מקצועי והתנסות מעשית ב-AI', 'הזמנת מומחי "בית רותר" להעברת סדנה מעשית לצוות ההוראה בנושא פתרונות AI וייעול עבודת המורה.', 'קיום הסדנה עד סוף נובמבר; 75% מהמורים מדווחים כי יישמו לפחות כלי AI אחד מהסדנה בתוך חודש.', 'צוות הוראה', 'אגף חדשנות', 12)
) as x(slug, title, short, description, metrics, audience, contact, position);


-- עיקרון 4 · חינוך טכנולוגי הוליסטי וספירלי (38 פעילויות)
insert into public.activity_bank_items (
  scope, municipality_id, principle_id, slug, title, category, source,
  short, description, metrics, audience, contact, position, is_active
)
select 'municipal',
       (select id from public.municipalities where slug = 'holon'),
       (select id from public.principles
         where scope = 'municipal' and title = 'חינוך טכנולוגי הוליסטי וספירלי'),
       x.slug, x.title, '', 'עירוני'::public.task_source,
       x.short, x.description, x.metrics, x.audience, x.contact, x.position, true
from (values
    ('p4-01', 'בניית מפת מיומנויות דיגיטליות ספירלית', 'יצירת רצף פדגוגי דיגיטלי מותאם גיל', 'גיבוש מפת דרכים המגדירה אילו כלים דיגיטליים רוכש הלומד בכל שכבת גיל למניעת כפילויות.', 'מסמך מוסכם מאושר עד סוף ספטמבר; 100% מהמורים מכירים את הכלים הנדרשים לשכבה שלהם.', 'צוות הוראה', 'פסג״ה חולון', 1),
    ('p4-02', 'השקת "כלי החודש" לכלל הצוות', 'יצירת שפה דיגיטלית אחידה בבית הספר', 'התמקדות מוסדית בכלי דיגיטלי אחד מדי חודש שמוטמע בכלל שכבות הגיל לייצור שפה אחידה.', '8 כלים שנלמדו והוטמעו במהלך השנה; הצגת תוצרים מבוססי הכלי בישיבות צוות חודשיות.', 'צוות הוראה', 'אגף חדשנות', 2),
    ('p4-03', 'יצירת פורום סנכרון פדגוגי-טכנולוגי', 'סנכרון ושילוב טכנולוגיה בתוכנית הלימודים', 'ישיבות עבודה חודשיות בין רכז התקשוב לרכזי המקצועות לשילוב כלים בתוכנית הלימודים.', '9 פגישות מתועדות בשנה; יצירת לפחות יחידת לימוד רב-תחומית אחת בסוף כל מחצית.', 'רכזי מקצוע ורכז תקשוב', 'אגף חדשנות', 3),
    ('p4-04', 'החלפת מבחן מסורתי בפרויקט דיגיטלי רב-תחומי', 'קידום הערכה חלופית מבוססת תוצרים', 'הפחתת מבחנים פרונטליים במקצועות רבי-מלל לטובת משימות חקר דיגיטליות כגון בלוג או פודקאסט.', 'הפחתה של 20% במספר המבחנים המסורתיים בשכבת הפיילוט; 80% מהתלמידים הגישו תוצר דיגיטלי מלא.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 4),
    ('p4-05', 'פתיחת "תיק עבודות דיגיטלי" (E-Portfolio)', 'תיעוד ומעקב אחר התפתחות הלומד', 'יצירת מרחב ענן אישי לכל תלמיד לריכוז תוצרי הלמידה הדיגיטליים שלו ממגוון מקצועות.', '100% מתלמידי השכבות הרלוונטיות מחזיקים תיק דיגיטלי פעיל; מינימום 3 תוצרים מוזנים בכל מחצית.', 'תלמידים', 'אגף חדשנות', 5),
    ('p4-06', 'מינוי "שגרירי דיגיטל" מקרב התלמידים', 'פיתוח מנהיגות טכנולוגית בקרב תלמידים', 'בחירת 2-3 תלמידים בכל כיתה שישמשו כתומכי טכנולוגיה (Help Desk) במהלך השיעורים.', 'מינוי השגרירים עד אמצע ספטמבר; קיום שני מפגשי הדרכה שנתיים לשגרירים עם רכז התקשוב.', 'תלמידים', 'אגף חדשנות', 6),
    ('p4-07', 'חיבור לאקדמיה/תעשייה מקומית להשראה', 'חיבור הלמידה לעולם האמיתי ולתעשייה', 'שיתוף פעולה עם תעשייה טכנולוגית עירונית או אקדמיה ללמידת עמיתים, מנטורינג וסיורים.', 'חתימה על שותפות עם ארגון אחד לפחות; קיום סיור או הרצאת אורח אחת למחצית.', 'תלמידים', 'אגף חדשנות', 7),
    ('p4-08', 'הגדרת כלי דיגיטלי אחיד לשבועיים הראשונים', 'יישור קו טכנולוגי וביסוס ביטחון', 'החלטה מוסדית על כלי אחד שכל המורים ישתמשו בו בתחילת השנה, ליישור קו ורכישת ביטחון.', '100% ממחנכי הכיתות משתמשים בכלי הנבחר ב-14 הימים הראשונים ללימודים.', 'מחנכים ותלמידים', 'אגף חדשנות', 8),
    ('p4-09', 'שילוב טכנולוגיה במקצועות הומניים ואומנות', 'הרחבת השימוש בטכנולוגיה לכלל תחומי הדעת', 'הוצאת הטכנולוגיה משיעורי המדעים והמחשבים לתוך מקצועות כמו היסטוריה, ספרות ואמנות.', '3 יחידות לימוד של הצוות ההומניסטי הכוללות שימוש בפלטפורמות ענן ויצירה דיגיטלית.', 'מורי מקצועות הומניים', 'אגף חדשנות', 9),
    ('p4-10', 'קיום ערב "חשיפה דיגיטלית" להורים', 'רתימת ההורים לשינוי הטכנולוגי', 'מפגש להצגת הרציונל הספירלי, האוריינות הנדרשת ומוגנות ברשת, להפיכת ההורים לשותפים.', '60% נוכחות הורים; חלוקת דף מידע וכלים מעשיים להורים בסיום הערב.', 'הורים', 'אגף חדשנות', 10),
    ('p4-11', 'תוכנית קוד ורובוטיקה ליסודי (עם "אתחלא")', 'פיתוח חשיבה אלגוריתמית בגיל הרך', 'שילוב תוכנית חינוך טכנולוגי של מרכז "אתחלא" במערכת השעות של הכיתות הנמוכות לבניית חשיבה אלגוריתמית.', 'שיבוץ שעה שבועית קבועה במערכת לכל כיתות א''-ד''; משימת סיכום רובוטית בכל כיתה במחצית ב''.', 'תלמידי יסודי (א''-ד'')', 'אגף חדשנות', 11),
    ('p4-12', 'תוכנית "נערות לטכנולוגיה" (עם "בית רותר")', 'קידום שוויון מגדרי במקצועות ה-STEM', 'הפעלת תוכנית עירונית של מרכז "בית רותר" לעידוד וקידום נערות לבחירה במקצועות ה-STEM.', 'פתיחת קבוצת מנהיגות טכנולוגית לנערות; עלייה של 15% ברישום בנות למגמות טכנולוגיות בתיכון.', 'נערות', 'אגף חדשנות', 12),
    ('p4-13', 'שילוב המגמות הטכנולוגיות (עם "בית רותר")', 'העמקת הלמידה המעשית במגמות הטכנולוגיות', 'חיבור רציף בין תלמידי המגמות הטכנולוגיות בתיכון למעבדות ומומחי מרכז "בית רותר" לפרויקטי הגמר.', 'יום עבודה חודשי מרוכז במרכז לתלמידי המגמות; 100% מפרויקטי הגמר מלווים בייעוץ של צוות המרכז.', 'תלמידי מגמות טכנולוגיות', 'אגף חדשנות', 13),
    ('p4-14', 'חתימה על גאנט עבודה מול המרכזים העירוניים', 'הסדרת שיתופי הפעולה העירוניים', 'פגישת תיאום של ההנהלה עם מנהלי "אתחלא" ו"בית רותר" לתכנון מוקדם של השיבוצים.', 'מסמך עבודה חתום בשבועיים הראשונים, הכולל תיאום של מערך הסעות עירוני קבוע.', 'צוות הנהלה', 'אגף חדשנות', 14),
    ('p4-15', 'שיבוץ "בלוקים" במערכת לעבודה עירונית', 'יצירת רצפי למידה משמעותיים מחוץ לבית הספר', 'יצירת חצאי-ימים קבועים במערכת לשכבות מוגדרות ללמידה וליצירה מחוץ לבית הספר.', 'מינימום שכבת גיל אחת משובצת לבלוק עבודה רציף של 3-4 שעות שבועיות/דו-שבועיות במרכז העירוני.', 'תלמידים', 'אגף חדשנות', 15),
    ('p4-16', 'מינוי מורה מוביל מייקרינג וחדשנות', 'ביסוס מנהיגות מקצועית בתחום המייקרינג', 'הגדרת איש צוות שיתכלל את העבודה מול המרכזים ויחנוך מורים בתוך בית הספר.', 'מינוי מורה עד 1.9; קיום פגישת הדרכה שבועית/דו-שבועית של המורה עם צוות ההדרכה העירוני.', 'צוות הוראה', 'אגף חדשנות', 16),
    ('p4-17', 'הגדרת אתגר קהילתי לפרויקט PBL', 'חיבור הלמידה לצרכי הקהילה', 'איתור צורך אמיתי בעיר (עם הקהילה) שהתלמידים ייצרו עבורו פתרונות פיזיים ודיגיטליים.', 'בחירת 2 אתגרים קהילתיים בשנה; 90% מהקבוצות הגיעו לאב-טיפוס עובד העונה על האתגר.', 'תלמידים וקהילה', 'אגף חדשנות', 17),
