    ('p1-09', 'הדרכת מורים למתן משוב מעצב', 'קידום למידה מתמדת ושיפור עצמי', 'הכשרת הצוות למתן משוב איכותי שמתמקד בדרך שעשה התלמיד ובאסטרטגיה במקום בציון.', 'כל תלמיד מקבל לפחות משוב כתוב אחד במחצית שמתייחס ספציפית למיומנות שהפגין.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 9),
    ('p1-10', 'סנכרון עם אגף הפיתוח הפדגוגי בעיר', 'מיסוד דרכי ההערכה החדשות', 'עבודה מול הגורמים המקצועיים לאישור חלופות הערכה רשמיות המגובות בתוכניות הפיקוח.', 'אישור פורמלי ל-2 תוכניות חלופיות בהערכה; שיתוף התוצרי בפורטל העירוני.', 'צוות הנהלה', 'אגף חדשנות', 10),
    ('p1-11', 'מפגשי מליאה בנושא יזמות (עם "אתחלא")', 'פיתוח חשיבה יזמית בקרב הצוות', 'הקדשת ישיבות מליאה להרצאות ולסדנאות בהובלת "אתחלא" לחיזוק מיומנויות חשיבה יזמית לצוות.', 'קיום 2 מפגשי מליאה בנושא יזמות בשנה; יצירת 3 מיזמים חינוכיים חדשים על ידי המורים.', 'צוות הוראה', 'אגף חדשנות', 11),
    ('p1-12', 'הכשרת צוות להערכת מיומנויות (עם פסג"ה)', 'התמקצעות בהערכה חלופית', 'תהליך פיתוח מקצועי עם מרכז פסג"ה לבניית מחוונים והערכה חלופית המודדת ביצועים.', 'בניית 3 מחוונים בית-ספריים בשיתוף מנחי פסג"ה; שילוב המחוונים בלפחות 50% ממשימות ההערכה.', 'צוות הוראה', 'פסג״ה חולון', 12)
) as x(slug, title, short, description, metrics, audience, contact, position);


-- עיקרון 5 · גיוון במרחבי ובסביבות הלמידה (11 פעילויות)
insert into public.activity_bank_items (
  scope, municipality_id, principle_id, slug, title, category, source,
  short, description, metrics, audience, contact, position, is_active
)
select 'municipal',
       (select id from public.municipalities where slug = 'holon'),
       (select id from public.principles
         where scope = 'municipal' and title = 'גיוון במרחבי ובסביבות הלמידה'),
       x.slug, x.title, '', 'עירוני'::public.task_source,
       x.short, x.description, x.metrics, x.audience, x.contact, x.position, true
from (values
    ('p5-01', 'עיצוב והשמשת מרחב גמיש ראשון במסדרון', 'ניצול מיטבי של המרחב הפיזי ללמידה', 'ציוד שטח מבוזבז בריהוט נייד והפיכתו למרחב למידה פעיל לשימוש מיידי בפתיחת השנה.', 'המרחב פעיל ב-1.9; מורים מקיימים בו שיעורי היכרות לתרגול הלמידה במקום החדש.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 1),
    ('p5-02', 'ניהול "מערכת שעות של מרחבים"', 'גיוון סביבות הלמידה בשגרה', 'שילוב המרחבים המשותפים כמשאב במערכת השעות כך שמורים משבצים למידה חוץ-כיתתית.', '30% משעות הלימוד של שכבת הפיילוט מתקיימות מחוץ לכיתת האם (בספרייה/מבואות).', 'תלמידים וצוות הוראה', 'אגף חדשנות', 2),
    ('p5-03', 'סדנת "ניהול כיתה מבוזרת" לצוות', 'הקניית כלים לניהול למידה גמישה', 'הדרכת המורים כיצד להנחות למידה כאשר התלמידים מפוזרים במספר מוקדים במרחב.', 'קיום סדנה בת שעתיים; 80% מהמורים מרגישים ביטחון להנחות עבודה מחוץ לטווח ראייה מיידי.', 'צוות הוראה', 'אגף חדשנות', 3),
    ('p5-04', 'ביטול "המקום הקבוע" (ויתור ארגוני)', 'התאמת סביבת הלמידה למשימה', 'הפסקת הנוהג של כיסא קבוע לתלמיד כל היום, ומעבר לתנועה בין עמדות בהתאם למשימה.', 'הטמעת המודל בכיתות החלוץ; דיווח על הפחתת בעיות משמעת הנובעות מישיבה ממושכת.', 'תלמידים', 'אגף חדשנות', 4),
    ('p5-05', 'ביסוס סביבת למידה דיגיטלית קבועה (LMS)', 'הבטחת רציפות וגמישות בלמידה', 'הקפדה על מרחב דיגיטלי פעיל לאפשר למידה היברידית גמישה (בכיתה או מהבית).', '100% מהמקצועות מנוהלים בסביבת ענן; קיום יום למידה מרחוק פעם במחצית.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 5),
    ('p5-06', 'קביעת שגרות התנהגות למרחבים משותפים', 'יצירת אקלים מיטבי במרחבים המשותפים', 'ניסוח חוקים (כמו עוצמת קול) שיאפשרו עבודה רב-כיתתית משותפת מחוץ לכיתות המסורתיות.', 'יצירת כרזות לשגרות בכל מרחב; אפס תלונות על רעש המפריע לכיתות סמוכות.', 'תלמידים', 'אגף חדשנות', 6),
    ('p5-07', 'חשיבה ארכיטקטונית מול מחלקת בינוי', 'התאמת המבנה הפיזי לפדגוגיה החדשנית', 'יצירת תוכנית אב בשיתוף העירייה לפתיחת חללים, שיפור אקוסטיקה ורכישת ריהוט מודולרי.', 'הגשת פרוגרמה מסודרת לאישור הרשות המקומית; יישום פרויקט בינוי אחד במהלך חופשת הקיץ.', 'צוות הנהלה', 'אגף חדשנות', 7),
    ('p5-08', 'שינוי עמדת המורה בכיתה המסורתית', 'שינוי תפקיד המורה למנחה למידה', 'העברת הזרקור מעמידה ליד הלוח והנחיית המורה לנוע כ"מנחה" בין הקבוצות במרחב.', 'בתצפיות הנהלה, מורים מבלים פחות מ-20% מזמן השיעור עומדים ליד הלוח הראשי.', 'צוות הוראה', 'אגף חדשנות', 8),
    ('p5-09', 'סיור פדגוגי-אדריכלי לצוות החדשנות', 'הרחבת אופקים וקבלת השראה לעיצוב', 'ביקור בבתי ספר חלוציים או חללי עבודה שיתופיים כדי לשבור פרדיגמות של עיצוב מרחבים.', 'קיום סיור עד דצמבר; חברי הצוות מציגים 3 רעיונות יישומיים (מהירים) למבנה הקיים.', 'צוות חדשנות', 'אגף חדשנות', 9),
    ('p5-10', 'יצירת "אזורי שקט" ללמידה עצמאית', 'מתן מענה לשונות בצרכי הלמידה', 'הגדרת מתחמים לעבודה דוממת ומרוכזת, לתלמידים הזקוקים להפחתת גירויים.', 'הקמת 2 פינות שקטות; תלמידים עם קשיי קשב מדווחים על יכולת ריכוז גבוהה יותר.', 'תלמידים', 'אגף חדשנות', 10),
    ('p5-11', 'סדנאות לעיצוב מרחבים (בשילוב "אתחלא")', 'פיתוח יכולות תכנון מרחבים בצוות', 'סדנאות במרכז "אתחלא" לצוותים ללמידת עקרונות תכנון של מרחבי למידה טכנו-פדגוגיים.', 'השתתפות צוות ההיגוי; גיבוש תוכנית שרטוט להסבת מסדרון למרחב דינמי תוך חודשיים.', 'צוות היגוי', 'אגף חדשנות', 11)
) as x(slug, title, short, description, metrics, audience, contact, position);


-- עיקרון 2 · תפקיד המורה כמוביל למידה אנושית (11 פעילויות)
insert into public.activity_bank_items (
  scope, municipality_id, principle_id, slug, title, category, source,
  short, description, metrics, audience, contact, position, is_active
)
select 'municipal',
       (select id from public.municipalities where slug = 'holon'),
       (select id from public.principles
         where scope = 'municipal' and title = 'תפקיד המורה כמוביל למידה אנושית'),
       x.slug, x.title, '', 'עירוני'::public.task_source,
       x.short, x.description, x.metrics, x.audience, x.contact, x.position, true
from (values
    ('p2-01', 'פתיחת שנה ב"מרתון הקשבה" ושיחות אישיות', 'ביסוס קשר אישי ואמון בתחילת השנה', 'פתיחת השנה בשיחות היכרות חמות בין מורים לתלמידים במקום מבחני מיפוי ישירים.', 'כל תלמיד מקיים שיחה אישית של 15 דקות לפחות עם מחנך/איש צוות בשבועיים הראשונים.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 1),
    ('p2-02', 'שריון חלונות למנטורינג במערכת השעות', 'מיסוד המענה הרגשי-אישי בשגרה', 'הגדרת זמנים קבועים ומוגנים במערכת המוקדשים לשיחות פרטניות או קבוצות שיח קטנות.', 'מורים משובצים לפחות לשעתיים שבועיות ייעודיות למנטורינג (מתוך שעות שהייה/פרטניות).', 'תלמידים וצוות הוראה', 'אגף חדשנות', 2),
    ('p2-03', 'צמצום ההרצאה הפרונטלית ל-15 דקות', 'קידום למידה פעילה ודיאלוגית', 'הגבלת ההקניה הפרונטלית לטובת עבודה עצמאית והנחיה דיאלוגית של המורה.', 'בתצפיות הנהלה מוכח שפתיחת השיעור אינה עולה על 15-20 דקות; רוב השיעור מוקדש לדיאלוג.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 3),
    ('p2-04', 'הקמת קהילת למידה מקצועית למנטורינג', 'פיתוח מקצועי ותמיכה רגשית לצוות', 'הקמת פורום פנימי לצוות לשיתוף דילמות רגשיות ולמידת פרקטיקות של הנחיה ומנטורינג.', 'מפגש קל"מ חודשי קבוע; הצוות מדווח על תחושת מסוגלות וכלים טובים לניהול שיח מורכב.', 'צוות הוראה', 'אגף חדשנות', 4),
    ('p2-05', 'הכנסת שגרות SEL (למידה רגשית-חברתית)', 'טיפוח מיומנויות רגשיות וחברתיות', 'שילוב פרקטיקות של מודעות עצמית ואמפתיה כחלק משגרת הבוקר או פתיחת שיעורים.', '100% מהמחנכים מקיימים "מעגל בוקר" או שגרת שיתוף פעמיים בשבוע לפחות.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 5),
    ('p2-06', 'קביעת "מבוגר משמעותי" לכל תלמיד', 'הבטחת מעטפת תמיכה אישית לכל תלמיד', 'מיפוי ארגוני המבטיח שלכל תלמיד יש לפחות מורה אחד המלווה אותו אישית לאורך השנה.', 'בסקר סוף שנה, 95% מהתלמידים מציינים שם של איש צוות אליו יפנו בעת משבר אישי.', 'תלמידים', 'אגף חדשנות', 6),
    ('p2-07', 'שילוב גורמי טיפול (שפ"ח) בהכשרת הצוות', 'חיזוק החוסן הנפשי והמוגנות', 'עבודה משותפת עם השירות הפסיכולוגי העירוני להכשרת המורים כמפתחי חוסן ומזהי מצוקות.', '2 השתלמויות מוסדיות בשנה על ידי פסיכולוג בית הספר סביב מוגנות וניהול רגשי.', 'צוות הוראה', 'אגף חדשנות', 7),
    ('p2-08', 'חיבור חברתי-ערכי לאקו-סיסטם בעיר', 'פיתוח מעורבות חברתית ואזרחות פעילה', 'קידום מעורבות חברתית על ידי חיבור מורים ותלמידים לתנועות נוער וארגוני התנדבות.', '80% מהתלמידים פעילים במסגרת התנדבותית אחת; פתיחת 2 יוזמות חברתיות ביה"ס-קהילה.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 8),
    ('p2-09', 'מעבר למשוב דיאלוגי במקום ציונים יבשים', 'קידום למידה רפלקטיבית ומעצימה', 'פיתוח שיח הערכה מעצים המבוסס על רפלקציה עצמית של התלמיד יחד עם המורה.', 'כל חלוקת מבדק מלווה בשיח משוב של 5 דקות או במשימת רפלקציה עצמית של התלמיד.', 'תלמידים וצוות הוראה', 'אגף חדשנות', 9),
    ('p2-10', '"שעון נוכחות רגשי" (Check-in דיגיטלי/פיזי)', 'זיהוי מוקדם של מצוקות ומתן מענה', 'הנהגת שגרה שבה התלמידים מסמנים את מצבם הרגשי בתחילת היום לתמיכה מיידית.', 'הטמעת שגרה דיגיטלית/פיזית בכל הכיתות; טיפול מהיר במקרים של קושי רגשי סמוי.', 'תלמידים', 'אגף חדשנות', 10),
    ('p2-11', 'תהליכי מנטורינג בליווי מרכז פסג"ה', 'התמקצעות בניהול שיח רגשי', 'תוכנית שנתית של קהילות למידה עם פסג"ה, להקניית כלים למנטורינג וניהול שיח רגשי.', 'אישור התוכנית מול פסג"ה ב-1.9; הגשת עבודת רפלקציה על שיחות אישיות על ידי 80% מהצוות.', 'צוות הוראה', 'פסג״ה חולון', 11)
) as x(slug, title, short, description, metrics, audience, contact, position);


-- guard: the load must produce exactly the sheet's 84 rows across the 5 principles.
do $$
begin
  if (select count(*) from public.activity_bank_items) <> 84 then
    raise exception 'activity bank load: expected 84 rows, got %',
      (select count(*) from public.activity_bank_items);
  end if;
  if exists (select 1 from public.activity_bank_items where principle_id is null) then
    raise exception 'activity bank load: some rows did not resolve a principle';
  end if;
end $$;
